import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { expect, it, vi } from "vitest";
import { ReviewForm } from "./review-form";

it("shows the action's errors, then its message", async () => {
  const action = vi
    .fn()
    .mockResolvedValueOnce({ errors: { title: ["Give your review a title"] }, values: { rating: "4", title: "", body: "" } })
    .mockResolvedValueOnce({ message: "Thanks! Your review is up." });
  const user = userEvent.setup();
  render(<ReviewForm action={action} />);

  await user.selectOptions(screen.getByLabelText("Rating"), "4");
  await user.click(screen.getByRole("button", { name: "Post review" }));
  expect(await screen.findByText("Give your review a title")).toBeInTheDocument();

  await user.type(screen.getByLabelText("Title"), "Light and roomy");
  await user.click(screen.getByRole("button", { name: "Post review" }));
  expect(await screen.findByText("Thanks! Your review is up.")).toBeInTheDocument();

  const formData = action.mock.calls[1][1] as FormData;
  expect(formData.get("title")).toBe("Light and roomy");
});

import react from "@vitejs/plugin-react";
import { defineConfig } from "vitest/config";

export default defineConfig({
  plugins: [react()],
  resolve: { tsconfigPaths: true },
  test: {
    environment: "jsdom",
    setupFiles: ["./vitest.setup.ts"],
    include: ["**/*.test.{ts,tsx}"],
