// vitest.setup.ts
import "@testing-library/jest-dom/vitest";
import { cleanup } from "@testing-library/react";
import { afterEach } from "vitest";

afterEach(() => cleanup());

import { render, screen } from "@testing-library/react";
import { usePathname } from "next/navigation";
import { describe, expect, it, vi } from "vitest";
import { NavLink } from "./nav-link";

vi.mock("next/navigation", () => ({ usePathname: vi.fn() }));

describe("NavLink", () => {
  it("marks the link for the current section", () => {
    vi.mocked(usePathname).mockReturnValue("/products/trail-pack-45");
    render(<NavLink href="/products">Products</NavLink>);
    expect(screen.getByRole("link", { name: "Products" })).toHaveAttribute("aria-current", "page");
  });

  it("leaves other links unmarked", () => {
    vi.mocked(usePathname).mockReturnValue("/cart");
    render(<NavLink href="/products">Products</NavLink>);
    expect(screen.getByRole("link", { name: "Products" })).not.toHaveAttribute("aria-current");
  });
});

// @vitest-environment node
import { http, HttpResponse } from "msw";
import { setupServer } from "msw/node";
import { updateTag } from "next/cache";
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";
import { createReview } from "./actions";

vi.mock("server-only", () => ({}));
vi.mock("next/cache", () => ({ updateTag: vi.fn() }));
vi.mock("next/headers", () => ({
  cookies: async () => ({ get: (name: string) => (name === "th_session" ? { name, value: "token-1" } : undefined) }),
}));

const API = "http://api.test/v1";
const server = setupServer();

beforeAll(() => server.listen({ onUnhandledFrame: "error" }));
beforeEach(() => vi.stubEnv("API_URL", API));
afterEach(() => {
  server.resetHandlers();
  vi.clearAllMocks();
});
afterAll(() => server.close());

function reviewForm(fields: Record<string, string>) {
  const formData = new FormData();
  for (const [name, value] of Object.entries(fields)) formData.set(name, value);
  return formData;
}

describe("createReview", () => {
  it("returns field errors without calling the API", async () => {
    const state = await createReview("trail-pack-45", {}, reviewForm({ rating: "4", title: "  ", body: "Roomy" }));
    expect(state.errors).toEqual({ title: ["Give your review a title"] });
    expect(updateTag).not.toHaveBeenCalled();
  });

  it("posts the review with the session and expires the cached reviews", async () => {
    let sent: { cookie: string | null; body: unknown } | undefined;
    server.use(
      http.post(`${API}/products/trail-pack-45/reviews`, async ({ request }) => {
        sent = { cookie: request.headers.get("cookie"), body: await request.json() };
        return HttpResponse.json({ id: "r_9" }, { status: 201 });
      }),
    );

    const state = await createReview("trail-pack-45", {}, reviewForm({ rating: "4", title: "Light and roomy", body: "Fits a weekend's gear." }));

    expect(state).toEqual({ message: "Thanks! Your review is up." });
    expect(sent).toEqual({ cookie: "th_session=token-1", body: { rating: 4, title: "Light and roomy", body: "Fits a weekend's gear." } });
    expect(updateTag).toHaveBeenCalledWith("reviews-trail-pack-45");
  });

  it("sends a logged-out visitor to the login page", async () => {
    server.use(
      http.post(`${API}/products/trail-pack-45/reviews`, () =>
        HttpResponse.json({ type: "about:blank", title: "Unauthorized", status: 401 }, { status: 401 }),
      ),
    );

    const result = createReview("trail-pack-45", {}, reviewForm({ rating: "5", title: "Great", body: "Carries well." }));

    await expect(result).rejects.toThrow("NEXT_REDIRECT");
    await expect(result).rejects.toMatchObject({ digest: expect.stringContaining("/login?next=/products/trail-pack-45") });
  });

  it("refuses a slug that isn't one", async () => {
    await expect(createReview("../me", {}, reviewForm({ rating: "5", title: "Hi", body: "" }))).rejects.toThrow();
  });
});

steps.body:
Vitest proves the pieces work. Only a real browser on a running app proves they work together: that the login cookie reaches the action, that the page streams its cart count, that a link moves to the next page without reloading. That's Playwright's job, which the React course set up for a Vite app. With Next.js, one choice matters more than any other: run it against a production build.

## Test the build, not next dev

`next dev` is made for editing. It compiles each page the first time you open it, adds its error overlay and developer tools, and skips the prerendering, the static shells, and much of the caching that `next build` does. A test against it is slower, and it isn't testing what your visitors get. A page that would fail to prerender, or a cache that serves stale data, only shows up in a build. The Next.js docs recommend testing your production code for that reason.

So Playwright's `webServer` option, which starts servers before the tests and stops them after, runs `npm run build && npm run start`, and the `start` script serves the build at `http://127.0.0.1:3005`, the course's address for the shop. The first example shows the whole `playwright.config.ts`. It starts two servers, in order: the Trailhead API on port 4000, from the `trailhead-api` folder next to your project, then the app, built with `API_URL` pointing at it. Playwright waits until each `url` answers before it runs anything. `reuseExistingServer` lets you keep both running between runs on your own computer, while CI always starts fresh.

## Log in once with a setup project

Most journeys need a logged-in visitor, and logging in through the form in every test is slow. A **setup project** logs in once, then saves the browser's cookies to a file with `page.context().storageState({ path })`. Every test in the `chromium` project starts with that file loaded, because the config lists it as `storageState` and makes the project depend on `setup`. Here's `e2e/auth.setup.ts`:

```ts
import { expect, test as setup } from "@playwright/test";

setup("log in as Sam", async ({ page, request }) => {
  const reset = await request.post("http://127.0.0.1:4000/__reset");
  expect(reset.status()).toBe(204);

  await page.goto("/login?next=/products");
  await page.getByLabel("Email").fill("sam@example.com");
  await page.getByLabel("Password").fill("trailhead");
  await page.getByRole("button", { name: "Log in" }).click();
  await expect(page.getByRole("heading", { name: "All products" })).toBeVisible();
  await page.context().storageState({ path: "playwright/.auth/sam.json" });
});
```

That file holds a real session cookie, so add `/playwright/.auth` to `.gitignore`, next to `/test-results` and `/playwright-report`. A test that needs a logged-out visitor overrides it with `test.use({ storageState: { cookies: [], origins: [] } })`.

## Fresh data for every run

Tests change data: the review test posts a review as Sam, and the Trailhead API answers `409` when someone reviews the same product twice. The API keeps its data in memory and starts from the same seed data every time it starts, which is what CI gets. On your own computer, `reuseExistingServer` keeps it running between runs, so the config starts it with `TRAILHEAD_TEST=1`. That adds one endpoint, `POST /__reset`, which puts the seed data back, and the setup project calls it before it logs in, so every run begins from the same data. If you started the API yourself without that setting, the reset answers `404` and the setup fails, so start it with `TRAILHEAD_TEST=1 node trailhead-api/server.mjs`. Inside a run, the tests run in parallel, so give each one its own product to change. Against a real backend, you'd reset a test database the same way.

## Streaming and navigation

Playwright's assertions wait. `expect(locator).toBeVisible()` checks again and again until the element appears, or five seconds pass. That makes streamed content easy to test: assert on the final text, like `In your cart: 0`, and the assertion waits for the Suspense boundary to fill in. In the copy of the shop these tests run against, the product page shows the visitor's cart count as a line of its own, with Checking your cart... as its fallback. It's the same kind of hole as the header's cart count in the lesson on rendering modes.

To check what the page shows before the stream arrives, the static shell from the caching lesson, the `@next/playwright` package has an `instant()` helper. Inside its callback, Next.js holds back everything that would stream, so you can assert that the heading is there and the cart count isn't yet. It needs Next.js's testing API, which a production build includes only when `experimental.exposeTestingApiInProductionBuild` is on in `next.config.ts`. The config sets `EXPOSE_TESTING_API=1` for the test build, and `next.config.ts` turns the option on only when that variable is set, so builds for real visitors never include it.

A navigation test clicks a `Link` and checks the new URL and heading. To prove the page didn't reload, set a value on `window` first and check it's still there after the click, since a full reload would start a fresh `window`.

