import { defineConfig, devices } from "@playwright/test";

export default defineConfig({
  testDir: "./e2e",
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  reporter: process.env.CI ? [["github"], ["html", { open: "never" }]] : "list",
  use: {
    baseURL: "http://127.0.0.1:3005",
    trace: "on-first-retry",
  },
  projects: [
    { name: "setup", testMatch: /.*\.setup\.ts/ },
    {
      name: "chromium",
      use: { ...devices["Desktop Chrome"], storageState: "playwright/.auth/sam.json" },
      dependencies: ["setup"],
    },
  ],
  webServer: [
    {
      command: "node ../trailhead-api/server.mjs",
      url: "http://127.0.0.1:4000/v1/products",
      env: { TRAILHEAD_TEST: "1" },
      reuseExistingServer: !process.env.CI,
    },
    {
      command: "npm run build && npm run start",
      url: "http://127.0.0.1:3005",
      env: { API_URL: "http://127.0.0.1:4000/v1", EXPOSE_TESTING_API: "1" },
      reuseExistingServer: !process.env.CI,
      timeout: 180_000,
    },
  ],
});

import { instant } from "@next/playwright";
import { expect, test } from "@playwright/test";

test("posts a review and sees it in the list", async ({ page }) => {
  await page.goto("/products/ridge-2p-tent");
  await page.getByLabel("Rating").selectOption("5");
  await page.getByLabel("Title").fill("Stays dry");
  await page.getByLabel("Review").fill("Kept two of us dry through a night of rain.");
  await page.getByRole("button", { name: "Post review" }).click();

  await expect(page.getByText("Thanks! Your review is up.")).toBeVisible();
  await expect(page.getByRole("listitem").filter({ hasText: "Stays dry" })).toContainText("by Sam");
});

test("the product page's shell arrives before the cart count", async ({ page, baseURL }) => {
  await instant(
    page,
    async () => {
      await page.goto("/products/trail-pack-45");
      await expect(page.getByRole("heading", { level: 1 })).toHaveText("Trail Pack 45L");
      await expect(page.getByText("Checking your cart...")).toBeVisible();
      await expect(page.getByText(/In your cart/)).toHaveCount(0);
    },
    { baseURL },
  );
  await expect(page.getByText(/In your cart: \d+/)).toBeVisible();
});

import { expect, test } from "@playwright/test";

test("page.route never sees the server's fetch to the API", async ({ page }) => {
  const seen: string[] = [];
  await page.route("**/v1/cart", (route) => {
    seen.push(route.request().url());
    return route.fulfill({ json: { items: [{ quantity: 99 }] } });
  });

  await page.goto("/products/trail-pack-45");
  const count = page.getByText(/In your cart: \d+/);
  await expect(count).toBeVisible();

  console.log(`page shows: ${await count.textContent()}`);
  console.log(`page.route caught: ${seen.length} requests`);
  expect(seen).toEqual([]);
});

import { expect, test } from "next/experimental/testmode/playwright";

test("answers the server's cart fetch from the test", async ({ page, next }) => {
  next.onFetch((request) => {
    if (new URL(request.url).pathname === "/v1/cart") {
      return Response.json({ items: [{ quantity: 7 }], subtotalCents: 0, currency: "USD" });
    }
    return "continue";
  });

  await page.goto("/cart");
  await expect(page.getByText("In your cart: 7")).toBeVisible();
});

import { expect, test } from "@playwright/test";

test("the product page looks the same", async ({ page }) => {
  await page.goto("/products/trail-pack-45");
  await expect(page.getByText(/In your cart: \d+/)).toBeVisible();

  await expect(page).toHaveScreenshot("product-page.png", {
    fullPage: true,
    mask: [page.getByText(/In your cart/)],
  });
});
